arguments.command:
mkdir -p tests/CheckoutPricing.UnitTests/Checkout && cd /tmp/vally-eval-trial-PBpN7b
cat > src/CheckoutPricing.Application/CalculatePayableTotal.cs <<'E'
namespace CheckoutPricing.Application;

public enum CustomerTier { Gold }

public sealed class CalculatePayableTotal
{
    public decimal Execute(CustomerTier tier, decimal subtotal) => default;
}
E
cat > tests/CheckoutPricing.UnitTests/Checkout/LoyaltyDiscountTests.cs <<'E'
using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests.Checkout;

public sealed class LoyaltyDiscountTests
{
    [Fact]
    public void Gold_customer_receives_the_approved_discount()
    {
        var payable = new CalculatePayableTotal().Execute(CustomerTier.Gold, 100.00m);

        Assert.Equal(95.00m, payable);
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests --verbosity quiet 2>&1 | tail -20

